import {languageField,bindLanguagePickers} from './language-picker.js';
import {languageName,languageDirection} from './languages.js';
import {parseHistory} from './history.js';
import {connection,connectLocal,api,extract,normalizeExplanation} from './api.js';
import {reports,labels,explain,validateFile,speechService,audioText} from './services.js';
import {t,languages,preferences,setPreference,formatDate,humanError,applyPreferences} from './i18n.js';
import {h,icon,button,options,toast,confirmAction,validateForm} from './ui.js';
const native=globalThis.HealthClearAndroid,$=s=>document.querySelector(s),root=$('#app');
document.body.classList.toggle('android-app',!!native);
let mounted=false;
let page='upload',current=null,result=null,lang=preferences.reportLanguage,objectURL=null,operation=0,cloudVersion=0;
let cloudSession='',cloudEmail='',pendingAuth=null,recovering=false,accountMode='login';
let service={configured:false,cloudConfigured:false};
const collection={query:'',filter:'all',sort:'newest'},cloudCollection={query:'',sort:'newest',offset:0};
function shell(){
 $('#skip-link').textContent=t('skip');$('#header-caption').textContent=t('noSave');
 const active=['review','results'].includes(page)?'upload':page;
 document.querySelectorAll('[data-nav]').forEach(a=>{a.innerHTML=icon(a.dataset.nav==='history'?'reports':a.dataset.nav)+`<span>${h(t(a.dataset.nav))}</span>`;a.classList.toggle('active',a.dataset.nav===active);if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#footer-note').textContent=t('disclaimer');networkStatus();applyPreferences();
}
function screen(name,html){page=name;root.dataset.screen=name;root.innerHTML=html;shell();window.scrollTo(0,0);const title=root.querySelector('h1');if(title){title.tabIndex=-1;if(mounted)title.focus({preventScroll:true});}mounted=true;}
function heading(title,description=''){return `<div class="page-heading"><h1>${h(t(title))}</h1>${description?`<p>${h(t(description))}</p>`:''}</div>`;}
function steps(n){return `<ol class="steps" aria-label="${h(t('understand'))}">${['upload','review','understand'].map((k,i)=>`<li class="step ${n===i?'on':''}" ${n===i?'aria-current="step"':''}><b aria-hidden="true">${i+1}</b><span>${h(t(k))}</span></li>`).join('')}</ol>`;}
function language(){return languageField('language',lang,!!current?.demo);}
function bindLanguage(fn){bindLanguagePickers();$('#language').onchange=event=>{lang=event.target.value;setPreference('reportLanguage',lang);speechService.stop();fn?.();};}
function clear(){operation++;cloudVersion++;speechService.stop();native?.closeReport();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;current=null;result=null;}
async function navigate(route){if(current&&!current.demo&&((current.draft!==undefined&&current.draft!==current.text)||(!current.saved&&!current.persisted&&(current.text||current.draft)))&&route!==page){if(!await confirmAction(t('leaveReport'),t('leaveHelp')))return;}clear();window.history.replaceState(null,'','#'+route);render(route);}
function render(route){if(route==='history')history();else if(route==='settings')settings();else if(route==='upload'||!route)upload();else screen('not-found',heading('notFound')+`<a class="button primary" href="#upload">${h(t('upload'))}</a>`);}
function networkStatus(){const el=$('#network-status');el.hidden=navigator.onLine;el.textContent=t('offline');}
window.addEventListener('online',networkStatus);window.addEventListener('offline',networkStatus);
function upload(){clear();screen('upload',heading('welcome','intro')+`<div class="workspace"><section class="card"><h2>${h(t('chooseReport'))}</h2><p>${h(t('reportTypes'))}</p><div class="service-status status" role="status">${h(t(service.sampleOnly?'freeGeminiStatus':service.configured?'serviceOnline':connection.ready?'servicePending':'serviceOffline'))}</div><div class="drop" id="drop">${icon('upload')}<p class="fine">${h(t('formats'))}</p><label class="consent"><input id="consent" type="checkbox"><span>${h(t(connection.ready?'consentOnline':'consentLocal'))}</span></label><div class="actions">${button('choose','chooseFile',true)}${button('camera','camera',false,icon('camera'))}</div><input id="file" type="file" accept="image/jpeg,image/png,application/pdf" hidden><input id="capture" type="file" accept="image/jpeg,image/png" capture="environment" hidden></div><details><summary>${h(t('processing'))}</summary><p>${h(t('processingNotice'))}</p><p>${h(t('noSave'))}</p><a href="#settings">${h(t('privacy'))}</a></details><p class="fine">${h(t('scanNotice'))}</p><div id="error" role="alert"></div></section><aside class="card sample-card"><span class="eyebrow">${h(t('fictional'))}</span><h2>${h(t('samples'))}</h2><p>${h(t('sampleNotice'))}</p><div class="sample-types">${Object.keys(reports).map(id=>`<button data-sample="${id}">${icon('reports')}${h(t(id))}${icon('arrow')}</button>`).join('')}</div></aside></div><div class="disclaimer">${icon('shield')}<span>${h(t('disclaimer'))}</span></div>`);
 $('#choose').onclick=()=>pick('file');$('#camera').onclick=()=>pick('capture');['file','capture'].forEach(id=>$('#'+id).onchange=e=>loadFile(e.target.files[0]));$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0]);};document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>{clear();const id=b.dataset.sample;if(!reports[id].copy[lang]){lang='en';toast(t('sampleLanguages'));}current={id,name:reports[id].name,text:reports[id].lines.join('\n'),demo:true};review();});
}
function pick(id){if(!$('#consent').checked){toast(t('consentRequired'));$('#consent').focus();return;}if(native)native.pickFile(id==='capture');else $('#'+id).click();}
let uploadPending=false;
async function analysisReady(){if(!connection.ready)await connectLocal();if(!connection.ready)throw Error(t('serviceRequired'));service=await api('status');if(service.sampleOnly)throw Error(t('freeGeminiNotice'));if(!service.configured)throw Error(t('analysisNotConfigured'));}
function showUploadFailure(message){if(!$('#error'))return;$('#error').textContent=message;$('#error').tabIndex=-1;$('#error').focus();$('#error').scrollIntoView({block:'nearest'});}
async function loadFile(file){if(uploadPending||!file)return;if(!$('#consent')?.checked){toast(t('consentRequired'));return;}uploadPending=true;const uploadScreen=root.firstElementChild;try{await validateFile(file);await analysisReady();if(page!=='upload'||root.firstElementChild!==uploadScreen)return;objectURL=URL.createObjectURL(file);current={name:file.name,type:file.type,file,demo:false,text:'',consent:true,busy:true,status:'extracting',translations:{}};review();runOcr();}catch(e){if(page==='upload'&&root.firstElementChild===uploadScreen)showUploadFailure(e.message===t('freeGeminiNotice')||e.message===t('analysisNotConfigured')||e.message===t('serviceRequired')?e.message:humanError(e));}finally{uploadPending=false;if($('#file'))$('#file').value='';if($('#capture'))$('#capture').value='';}}
function syncReviewControls(){if(page!=='review'||!current)return;const text=$('#extracted').value,unreadable=!text.trim()||/\[unreadable\]|\?\?/i.test(text);$('#continue').disabled=!!(current.busy||current.blocked||unreadable);$('#verified').disabled=!!(current.busy||current.blocked||unreadable);if(unreadable)$('#verified').checked=false;}
async function runOcr(){const target=current,version=++operation;target.busy=true;target.failure='';$('#review-error').textContent='';$('#continue').disabled=true;$('#retry-ocr').disabled=true;$('#extracted').disabled=true;$('#verified').disabled=true;$('#verified').checked=false;$('#ocr-status').textContent=t('extracting');$('#ocr-status').setAttribute('aria-busy','true');try{const output=await extract(target.file);if(version!==operation||target!==current)return;target.blocked=output.documentType!=='written_report';target.text=output.lines.map(l=>l.uncertain&&!l.text.includes('[unreadable]')?l.text+' [unreadable]':l.text).join('\n');target.status=target.blocked?'scanBlocked':!target.text.trim()?'emptyExtraction':output.lines.some(l=>l.uncertain)?'uncertain':'extractedReady';target.translations={};delete target.draft;$('#extracted').value=target.text;}catch(e){if(version!==operation||target!==current)return;target.status='ocrFailed';target.failure=humanError(e);}finally{if(version===operation&&target===current&&page==='review'){target.busy=false;$('#extracted').disabled=!!target.blocked;const message=target.failure||t(target.status);$('#ocr-status').textContent=message;$('#ocr-status').setAttribute('aria-busy','false');$('#review-error').textContent=target.failure||(['emptyExtraction','scanBlocked','uncertain'].includes(target.status)?message:'');$('#retry-ocr').disabled=false;syncReviewControls();}}}

function sourceLines(){return current.text.split(/\r?\n/).map((line,i)=>`<div class="source-line" dir="auto" id="source-${i}" tabindex="-1"><small>${i+1}</small> ${h(line)}</div>`).join('');}
function original(){if(current.saved)return `<p class="fine">${h(t('savedText'))}</p>${sourceLines()}`;if(current.demo)return `<div class="banner">${h(t('fictional'))}</div>${sourceLines()}`;if(native&&current.type==='application/pdf')return `<div class="actions">${button('pdf-prev','previous')}<span id="pdf-number"></span>${button('pdf-next','next')}</div><img id="pdf-page" alt="${h(t('original'))}">`;if(current.type==='application/pdf')return `<object data="${h(objectURL)}" type="application/pdf" aria-label="${h(t('original'))}"><a href="${h(objectURL)}" target="_blank" rel="noopener">${h(t('original'))}</a></object>`;return `<img src="${h(objectURL)}" alt="${h(t('original'))}">`;}
function setupPdf(){if(native&&current.type==='application/pdf'&&$('#pdf-page')){current.pdfPage=0;$('#pdf-prev').onclick=()=>native.pdfPage(current.pdfPage-1);$('#pdf-next').onclick=()=>native.pdfPage(current.pdfPage+1);native.pdfPage(0);}}
function processingConsent(){return `<label class="consent"><input id="saved-consent" type="checkbox" ${current.consent?'checked':''}><span>${h(t('savedConsent'))}</span></label>`;}
function bindSavedConsent(){if($('#saved-consent'))$('#saved-consent').onchange=e=>current.consent=e.target.checked;}
function review(){operation++;screen('review',heading('reviewTitle','verifyHelp')+steps(1)+`<div class="banner" id="ocr-status" role="status" aria-busy="${!!current.busy}">${h(current.failure||t(current.demo?'fictional':current.status||'verifyHelp'))}</div><div class="workspace"><section class="card"><h2>${h(t('review'))}</h2><label for="extracted">${h(t('extracted'))}</label><textarea id="extracted" spellcheck="false" maxlength="30000">${h(current.draft??current.text)}</textarea><div class="toolbar">${language()}</div>${current.saved&&!current.demo?processingConsent():''}<label class="consent"><input id="verified" type="checkbox"><span>${h(t('verified'))}</span></label><div id="review-error" role="alert"></div><div class="actions">${button('continue','explain',true)}${button('back','back')}${current.file&&current.consent?button('retry-ocr','retry'):''}</div></section><aside class="card original"><h2>${h(t('original'))}</h2><p class="fine">${h(current.name)}</p>${original()}</aside></div>`);bindLanguage();bindSavedConsent();setupPdf();$('#continue').disabled=!!(current.busy||current.blocked);$('#extracted').disabled=!!current.busy;$('#verified').disabled=!!current.busy;if($('#retry-ocr'))$('#retry-ocr').onclick=async()=>{if(current.draft!==undefined&&current.draft!==current.text&&!await confirmAction(t('leaveReport'),t('leaveHelp')))return;runOcr();};$('#back').onclick=()=>navigate('upload');$('#extracted').oninput=()=>{current.draft=$('#extracted').value;$('#verified').checked=false;syncReviewControls();};$('#continue').onclick=async()=>{const text=$('#extracted').value,error=$('#review-error');error.textContent='';if(!text.trim()||/\[unreadable\]|\?\?/i.test(text)){error.textContent=t('unreadable');return;}if(!$('#verified').checked){error.textContent=t('verifyFirst');return;}if(!current.demo&&!current.consent){error.textContent=t('consentRequired');return;}const target=current,version=++operation;$('#continue').disabled=true;$('#extracted').disabled=true;$('#language').disabled=true;$('#verified').disabled=true;$('#continue').textContent=t('working');try{if(target.demo)result=explain(target.id,text,lang);else result=normalizeExplanation(await api('explain',{text,language:lang,consent:true}),text,lang,labels);if(version!==operation||current!==target)return;target.text=text;target.result=result;target.resultLang=lang;target.translations={[lang]:{text,result}};results();}catch(e){if(target===current&&$('#review-error')){$('#review-error').textContent=humanError(e);$('#continue').disabled=false;$('#extracted').disabled=false;$('#language').disabled=false;$('#verified').disabled=false;$('#continue').textContent=t('retry');syncReviewControls();}}};syncReviewControls();}
function source(ref){if(!Number.isInteger(ref)||ref<0||ref>=current.text.split(/\r?\n/).length)return '';return `<a href="#source-${ref}" data-source="${ref}" class="source-link">${h(result.labels.source)} · ${ref+1} ↗</a>`;}
function bindSources(){document.querySelectorAll('[data-source]').forEach(a=>a.onclick=e=>{e.preventDefault();document.querySelectorAll('.highlight').forEach(x=>x.classList.remove('highlight'));const line=$('#source-'+a.dataset.source);if(line){line.classList.add('highlight');line.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});line.focus({preventScroll:true});}});}
function results(){if(current.demo)result=explain(current.id,current.text,lang);else result=current.result;const e=result,l=e.labels;screen('results',heading('resultsTitle')+steps(2)+`<div class="banner">${h(t(current.demo?'sampleNotice':'aiNotice'))}</div><div class="toolbar">${language()}${button('download','export')}${current.demo||native?button('save','saveLocal'):''}${!current.demo&&cloudSession?button('cloud-save','saveCloud'):''}${button('new','newReport')}</div><p class="fine">${h(t('saveHelp'))}</p>${current.saved&&!current.demo?processingConsent():''}<div class="workspace"><section class="card"><div id="explanation" lang="${lang}" dir="${languageDirection(lang)}"><h2>${h(l.summary)}</h2><p>${h(e.summary)}</p><h2>${h(l.finding)}</h2>${e.findings.map(f=>`<div class="finding"><p>${h(f.text)}</p>${f.quote?`<blockquote class="exact-quote" dir="auto"><small>${h(t('exactQuote'))}</small>${h(f.quote)}</blockquote>`:''}${f.value?`<p><strong>${h(f.value)}</strong></p>`:''}${f.rangeText||f.outside?`<span class="chip">${h(f.rangeText||l.outside)}</span><br>`:''}${source(f.ref)}</div>`).join('')}<div class="finding"><h3>${h(l.limits)}</h3><p>${h(l.limit)}</p></div><div class="finding"><h3>${h(l.terms)}</h3><p class="preserve-lines">${h(e.terms)}</p></div><div class="finding"><h3>${h(l.follow)}</h3><p class="preserve-lines">${h(e.follow)}</p>${(e.followRefs||[e.followRef]).map(source).join(' ')}</div><div class="finding"><h3>${h(l.questions)}</h3><p class="preserve-lines">${h(e.questions)}</p></div><p class="fine">${h(l.context)}</p></div><section class="audio"><h2>${h(t('listen'))}</h2><p>${h(t('audioNotice'))}</p><div class="actions">${button('play','play')}${button('pause','pause')}${button('replay','replay')}<div class="field"><label for="speed">${h(t('speed'))}</label><select id="speed">${options({'0.8':'0.8×','1':'1×','1.25':'1.25×','1.5':'1.5×'},preferences.speed)}</select></div></div><div id="audio-status" role="status"></div></section><h2>${h(t('askTitle'))}</h2><p class="fine">${h(t(current.demo?'sampleChat':'askHelp'))}</p><div class="questions">${['qTerm','qRange','qDoctor','qFollow'].map((key,i)=>`<button data-question="${i}">${h(t(key))}</button>`).join('')}</div>${current.demo?'':`<form novalidate id="ask"><label for="question">${h(t('question'))}</label><textarea id="question" maxlength="500" rows="2" required style="min-height:90px"></textarea><div class="actions"><button class="primary">${h(t('ask'))}</button></div></form>`}<div id="answer" role="status"></div><section id="conversation" aria-label="${h(t('conversation'))}"></section></section><aside class="card original"><h2>${h(t('original'))}</h2><p class="fine">${h(current.name)}</p>${original()}${!current.demo&&!current.saved?`<h3>${h(t('sourceText'))}</h3>${sourceLines()}`:''}</aside></div>`);bindLanguage(changeLanguage);bindSources();bindSavedConsent();setupPdf();$('#download').onclick=download;if($('#save'))$('#save').onclick=saveLocal;if($('#cloud-save'))$('#cloud-save').onclick=saveCloud;$('#new').onclick=()=>navigate('upload');$('#play').onclick=()=>play(false);$('#replay').onclick=()=>play(true);$('#pause').onclick=()=>{if(native)native.pause();else globalThis.speechSynthesis?.pause();$('#audio-status').textContent=t('paused');};$('#speed').onchange=e=>{setPreference('speed',e.target.value);speechService.stop();$('#audio-status').textContent=t('speedChanged');};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>answer(+b.dataset.question));if($('#ask'))$('#ask').onsubmit=e=>{e.preventDefault();const invalid=validateForm($('#ask'));if(invalid){$('#answer').textContent=invalid;return;}askLive($('#question').value);};renderConversation();}
async function changeLanguage(){if(current.chatBusy){lang=current.resultLang;$('#language').value=lang;toast(t('busy'));return;}if(current.demo){results();return;}if(!current.consent){lang=current.resultLang;results();toast(t('consentRequired'));return;}const target=current,requested=lang,version=++operation;lang=target.resultLang;const cached=target.translations?.[requested];if(cached?.text===target.text){lang=requested;target.result=cached.result;target.resultLang=lang;results();return;}$('#language').disabled=true;toast(t('working'));try{const data=await api('explain',{text:target.text,language:requested,consent:true});if(version!==operation||target!==current)return;lang=requested;target.result=normalizeExplanation(data,target.text,lang,labels);target.resultLang=lang;target.translations??={};target.translations[lang]={text:target.text,result:target.result};results();}catch(e){if(target===current){lang=target.resultLang;results();toast(humanError(e));}}}
function play(restart){try{if(native){native.speak(audioText(result),lang,+preferences.speed,restart);return;}if(!restart&&globalThis.speechSynthesis?.paused){speechSynthesis.resume();$('#audio-status').textContent=t('playing');return;}const utterance=speechService.play(audioText(result),lang,+preferences.speed);$('#audio-status').textContent=t('playing');utterance.onend=()=>{if($('#audio-status'))$('#audio-status').textContent=t('finished');};utterance.onerror=()=>{if($('#audio-status'))$('#audio-status').textContent=t('audioUnavailable');};}catch(e){$('#audio-status').textContent=humanError(e);}}
function renderConversation(){const box=$('#conversation');if(!box)return;const messages=current.chat||[];box.innerHTML=messages.length?`<h3>${h(t('conversation'))}</h3><p class="fine">${h(t('conversationHelp'))}</p>${messages.map(m=>`<article class="chat-turn"><div class="chat-question"><small>${h(t('you'))}</small><p dir="auto">${h(m.question)}</p></div><div class="chat-answer"><small>${h(t('assistant'))} · ${h(languageName(m.language,preferences.language))}</small>${!m.data.enoughInformation?`<p>${h(t('insufficient'))}</p>`:''}${m.data.claims.map(c=>`<p lang="${m.language}" dir="${languageDirection(m.language)}">${h(c.text)}</p><blockquote class="exact-quote" dir="auto">${h(c.quote)}</blockquote>${source(c.ref)}`).join('')}${m.data.education?`<p><strong>${h(t('education'))}</strong></p><p lang="${m.language}" dir="${languageDirection(m.language)}">${h(m.data.education)}</p>`:''}</div></article>`).join('')}${button('clear-chat','clearConversation')}`:'';if($('#clear-chat'))$('#clear-chat').onclick=()=>{current.chat=[];renderConversation();};bindSources();}
async function askLive(question){if(current.demo){$('#answer').textContent=t('sampleChat');return;}if(!current.consent){toast(t('consentRequired'));return;}if(current.chatBusy)return;const target=current,requested=lang;target.chatBusy=true;$('#answer').className='answer';$('#answer').textContent=t('working');$('#answer').setAttribute('aria-busy','true');document.querySelectorAll('[data-question],#ask button').forEach(b=>b.disabled=true);try{const data=await api('chat',{text:target.text,language:requested,question,previousQuestions:(target.chat||[]).slice(-4).map(m=>m.question),consent:true});if(current!==target||page!=='results')return;target.chat=[...(target.chat||[]),{question,language:requested,data}].slice(-12);$('#answer').textContent='';$('#question').value='';renderConversation();$('#conversation .chat-turn:last-of-type')?.scrollIntoView({block:'nearest'});}catch(e){if(current===target&&$('#answer'))$('#answer').textContent=humanError(e);}finally{target.chatBusy=false;if(current===target&&page==='results'){$('#answer').setAttribute('aria-busy','false');document.querySelectorAll('[data-question],#ask button').forEach(b=>b.disabled=false);}}}

function answer(i){if(!current.demo){askLive(['Explain the terms in this report.','Which values are outside the reference ranges explicitly printed in the report?','What should I ask my doctor?','Does the report recommend a follow-up?'][i]);return;}const e=result,text=i===0?e.terms:i===1?e.findings.map(f=>f.text+(f.value?' '+f.value:'')).join('\n'):i===2?e.questions:e.follow;$('#answer').className='answer';$('#answer').innerHTML=`<p class="preserve-lines" lang="${lang}">${h(text)}</p>${i===1?e.findings.map(f=>source(f.ref)).join(' '):i===3?source(e.followRef):`<small>${h(t('education'))}</small>`}`;bindSources();}
function readHistory(){try{return parseHistory(native?native.getHistory():localStorage.getItem('healthclear-samples')||'[]',reports);}catch{toast(t('historyUnreadable'));return null;}}
function writeHistory(items){if(native){if(!native.saveHistory(JSON.stringify(items)))throw Error(t('historyUnreadable'));}else localStorage.setItem('healthclear-samples',JSON.stringify(items));}
function saveLocal(){try{if(!current.demo&&!native){toast(t('androidOnly'));return;}const items=readHistory();if(!items)return;if(items.some(r=>r.lang===lang&&(current.demo?r.id===current.id:r.live&&r.text===current.text))){toast(t('alreadySaved'));return;}if(items.length>=20){toast(t('historyFull'));return;}items.push(current.demo?{id:current.id,lang,date:new Date().toISOString()}:{live:true,name:current.name,text:current.text,result,lang,date:new Date().toISOString()});writeHistory(items);current.persisted=true;toast(t('saved'));}catch(e){toast(humanError(e));}}
function collectionControls(prefix,state,local=true){return `<div class="history-controls"><div class="field"><label for="${prefix}-search">${h(t('search'))}</label><input id="${prefix}-search" type="search" maxlength="100" value="${h(state.query)}"></div>${local?`<div class="field"><label for="${prefix}-filter">${h(t('filter'))}</label><select id="${prefix}-filter">${options({all:t('all'),personal:t('personal'),sample:t('fictional')},state.filter)}</select></div>`:''}<div class="field"><label for="${prefix}-sort">${h(t('sort'))}</label><select id="${prefix}-sort">${options({newest:t('newest'),oldest:t('oldest'),name:t('name')},state.sort)}</select></div></div>`;}
function history(){screen('history',heading('history','historyIntro')+`<section class="card"><h2>${h(t('localReports'))}</h2>${collectionControls('local',collection)}<div id="local-list" role="region" aria-label="${h(t('localReports'))}"></div></section><section class="card backend-card"><h2>${h(t('cloudReports'))}</h2>${cloudSession?collectionControls('cloud',cloudCollection,false):''}<div id="cloud-list" role="status"></div></section>`);renderLocalList();$('#local-search').oninput=e=>{collection.query=e.target.value;renderLocalList();};$('#local-filter').onchange=e=>{collection.filter=e.target.value;renderLocalList();};$('#local-sort').onchange=e=>{collection.sort=e.target.value;renderLocalList();};if(cloudSession){let timer;$('#cloud-search').oninput=e=>{cloudCollection.query=e.target.value;cloudCollection.offset=0;clearTimeout(timer);timer=setTimeout(refreshCloud,250);};$('#cloud-sort').onchange=e=>{cloudCollection.sort=e.target.value;cloudCollection.offset=0;refreshCloud();};}refreshCloud();}
function renderLocalList(){const items=readHistory(),list=$('#local-list');if(items===null){list.textContent=t('historyUnreadable');return;}const filtered=items.map((r,index)=>({r,index,name:r.live?r.name:t(r.id)})).filter(({r,name})=>(collection.filter==='all'||collection.filter==='personal'&&r.live||collection.filter==='sample'&&!r.live)&&name.toLocaleLowerCase(preferences.language).includes(collection.query.toLocaleLowerCase(preferences.language))).sort((a,b)=>collection.sort==='name'?a.name.localeCompare(b.name,preferences.language):(new Date(a.r.date)-new Date(b.r.date))*(collection.sort==='oldest'?1:-1));list.innerHTML=!filtered.length?`<div class="empty">${icon('reports')}<h3>${h(t(items.length?'noResults':'emptyHistory'))}</h3><p>${h(t('emptyHelp'))}</p><a class="button" href="#upload">${h(t('newReport'))}</a></div>`:`<p class="fine">${h(t('reportCount',{count:filtered.length}))}</p>${filtered.map(({r,index,name})=>`<article class="history-item"><div><strong>${h(name)}</strong><small>${h(t(r.live?'personal':'fictional'))} · ${h(formatDate(r.date))} · ${h(languageName(r.lang,preferences.language))}</small></div><div class="actions"><button data-open="${index}">${h(t('open'))}</button><button data-delete="${index}" class="danger">${h(t('delete'))}</button></div></article>`).join('')}`;list.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const r=items[+b.dataset.open];clear();lang=r.lang;if(r.live){current={name:r.name,text:r.text,result:{...r.result,labels:r.result.labels||labels[lang]||labels.en},resultLang:lang,demo:false,saved:true,consent:false,translations:{}};}else current={id:r.id,name:reports[r.id].name,text:reports[r.id].lines.join('\n'),demo:true};results();});list.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!await confirmAction(t('confirmDelete'),t('deleteHelp')))return;try{writeHistory(items.filter((_,i)=>i!==+b.dataset.delete));renderLocalList();$('#local-search').focus();toast(t('deleted'));}catch(e){toast(humanError(e));}});}
async function cloudCall(action,body={}){return api('cloud',{...body,action,session:cloudSession});}
async function refreshCloud(){const list=$('#cloud-list');if(!list)return;const version=++cloudVersion;if(!cloudSession){list.textContent=t('cloudSignIn');return;}list.innerHTML=`<div class="skeleton" aria-label="${h(t('working'))}"></div>`;try{const data=await cloudCall('list',{limit:50,offset:cloudCollection.offset,search:cloudCollection.query,sort:cloudCollection.sort});if(version!==cloudVersion||!list.isConnected)return;list.innerHTML=data.reports.length?data.reports.map(r=>`<article class="history-item"><div><strong>${h(r.name)}</strong><small>${h(formatDate(r.created_at))} · ${h(languageName(r.language,preferences.language))}</small></div><div class="actions"><button data-cloud-open="${h(r.id)}">${h(t('review'))}</button><button class="danger" data-cloud-delete="${h(r.id)}">${h(t('delete'))}</button></div></article>`).join(''):`<div class="empty"><p>${h(t('noResults'))}</p></div>`;list.innerHTML+=`<div class="actions"><button id="cloud-prev" ${cloudCollection.offset===0?'disabled':''}>${h(t('previous'))}</button><button id="cloud-next" ${data.reports.length<50?'disabled':''}>${h(t('next'))}</button></div>`;$('#cloud-prev').onclick=()=>{cloudCollection.offset=Math.max(0,cloudCollection.offset-50);refreshCloud();};$('#cloud-next').onclick=()=>{cloudCollection.offset+=50;refreshCloud();};list.querySelectorAll('[data-cloud-open]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const response=await cloudCall('open',{id:b.dataset.cloudOpen});if(!list.isConnected)return;const r=response.report;clear();lang=r.language;current={name:r.name,text:r.text,demo:false,saved:true,consent:false,translations:{}};review();}catch(e){toast(humanError(e));b.disabled=false;}});list.querySelectorAll('[data-cloud-delete]').forEach(b=>b.onclick=async()=>{if(!await confirmAction(t('confirmDelete'),t('deleteHelp')))return;b.disabled=true;try{await cloudCall('delete',{id:b.dataset.cloudDelete});refreshCloud();toast(t('deleted'));}catch(e){toast(humanError(e));b.disabled=false;}});}catch(e){if(version!==cloudVersion||!list.isConnected)return;list.innerHTML=`<p class="error">${h(humanError(e))}</p>${button('retry-cloud','retry')}`;$('#retry-cloud').onclick=refreshCloud;}}
async function saveCloud(){if(!cloudSession){toast(t('cloudSignIn'));return;}if(current.demo){toast(t('cloudSample'));return;}const target=current;if(target.cloudBusy)return;if(!await confirmAction(t('cloudConfirm'),t('cloudConfirmHelp')))return;target.cloudBusy=true;const saveKey=target.text+'\n'+lang;if(target.saveKey!==saveKey){target.requestId=crypto.randomUUID();target.saveKey=saveKey;}try{await cloudCall('save',{saveConsent:true,requestId:target.requestId,report:{name:target.name.slice(0,200),text:target.text,language:lang}});target.persisted=true;toast(t('saved'));}catch(e){toast(humanError(e));}finally{target.cloudBusy=false;}}
function settings(){screen('settings',heading('settings')+`<div class="workspace settings-layout"><div class="stack"><section class="card settings-preferences"><h2>${h(t('preferences'))}</h2><div class="preferences-grid"><div class="field"><label for="ui-language">${h(t('uiLanguage'))}</label><select id="ui-language">${options(languages,preferences.language)}</select></div>${languageField('default-language',preferences.reportLanguage)}<div class="field"><label for="theme">${h(t('theme'))}</label><select id="theme">${options({system:t('system'),light:t('light'),dark:t('dark')},preferences.theme)}</select></div><div class="field"><label for="text-size">${h(t('textSize'))}</label><select id="text-size">${options({standard:t('standard'),large:t('large')},preferences.textSize)}</select></div></div><p class="fine">${h(t('interfaceCoverage'))}</p></section><details class="card settings-disclosure" id="account-panel"><summary>${h(t('account'))}</summary><section id="account-card"></section></details><details class="card settings-privacy settings-disclosure"><summary>${h(t('privacy'))}</summary><p>${h(t('processingNotice'))}</p><p>${h(t('privacyLocal'))}</p><p>${h(t('privacyCloud'))}</p>${button('erase','erase')}</details></div><aside class="stack"><section class="card settings-service"><h2>${h(t('service'))}</h2><div class="service-status" role="status">${h(t(service.configured?'serviceOnline':connection.ready?'servicePending':'serviceOffline'))}</div><p class="fine">${connection.managed?h(t('serviceAuto')):''}</p>${button('recheck-service','recheck')}<details id="advanced-connection"><summary>${h(t('advancedSetup'))}</summary><p class="fine">${h(t('serviceHelp'))}</p><form novalidate id="connect"><label for="backend-url">${h(t('backendUrl'))}</label><input id="backend-url" type="url" autocomplete="off" value="${h(connection.url)}" required placeholder="https://your-backend.example.com"><label for="backend-token">${h(t('backendToken'))}</label><input id="backend-token" type="password" autocomplete="off" required minlength="32"><div class="actions"><button class="primary">${h(t('connect'))}</button>${button('disconnect','disconnect')}</div></form><div id="connection-message" role="status">${h(t(connection.ready?'connected':'localMode'))}</div>${native?.localDevelopment?.()?'<p class="fine">USB: http://127.0.0.1:8080</p>':''}</details></section><details class="card settings-help settings-disclosure"><summary>${h(t('help'))}</summary><p>${h(t('helpText'))}</p><p>${h(t('scanNotice'))}</p><p>${h(t('disclaimer'))}</p><p class="fine">${h(t('version'))}</p></details><details class="card settings-disclosure developer-card"><summary>${h(t('developer'))}</summary><div class="developer-body"><div class="developer-avatar" aria-hidden="true">PB</div><div><h2>${h(t('developer'))}</h2><strong>Punit Badyal</strong><p>${h(t('developerBio'))}</p><a class="button" href="https://github.com/punitbadyal01-blip" rel="noopener noreferrer">${h(t('github'))} ↗</a></div></div></details></aside></div>`);mountAccount();bindLanguagePickers();$('#recheck-service').onclick=refreshService;$('#ui-language').onchange=e=>{setPreference('language',e.target.value);$('#toast').hidden=true;settings();};$('#default-language').onchange=e=>{lang=e.target.value;setPreference('reportLanguage',lang);};$('#theme').onchange=e=>setPreference('theme',e.target.value);$('#text-size').onchange=e=>setPreference('textSize',e.target.value);$('#connect').onsubmit=async e=>{e.preventDefault();const invalid=validateForm($('#connect'));if(invalid){$('#connection-message').textContent=invalid;return;}const button=$('#connect button');button.disabled=true;$('#connection-message').textContent=t('working');try{cancelAuth();cloudSession='';cloudEmail='';connection.configure($('#backend-url').value,$('#backend-token').value);service=await api('status');if(page!=='settings')return;$('#backend-token').value='';$('#connection-message').innerHTML=`<p>${h(t(service.configured?'aiReady':'aiMissing'))}</p><p>${h(t(service.cloudConfigured?'cloudReady':'cloudMissing'))}</p>`;mountAccount();}catch(error){connection.disconnect();if($('#connection-message'))$('#connection-message').textContent=humanError(error);}finally{button.disabled=false;}};$('#disconnect').onclick=()=>{cancelAuth();cloudSession='';cloudEmail='';service={};connection.disconnect();settings();};$('#erase').onclick=async()=>{if(!await confirmAction(t('erase'),t('eraseHelp'),{typed:true}))return;try{if(native&&!native.clearHistory())throw Error();localStorage.removeItem('healthclear-samples');toast(t('deleted'));}catch(e){toast(humanError(e));}};}
function cancelAuth(){pendingAuth=null;native?.cancelGoogleSignIn?.();}
function mountAccount(){const box=$('#account-card');if(!box)return;if(cloudSession||pendingAuth||recovering)$('#account-panel').open=true;box.innerHTML=`<h2>${h(t('account'))}</h2><p class="fine">${h(t('accountHelp'))}</p>${cloudSession?`<div class="account-state">${h(cloudEmail)}</div><div class="actions">${button('logout','signOut')}</div>${recovering?`<form novalidate id="password-update"><h3>${h(t('newPassword'))}</h3><label for="new-password">${h(t('password'))}</label><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><label for="confirm-password">${h(t('confirmPassword'))}</label><input id="confirm-password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><div class="actions"><button class="primary">${h(t('confirm'))}</button></div></form>`:''}<details><summary>${h(t('deleteAccount'))}</summary><p>${h(t('accountDeleteHelp'))}</p>${button('delete-account','deleteAccount')}</details>`:`${native?button('google-login','google',false):''}${pendingAuth?`<div class="banner">${h(t('waiting'))}${button('cancel-auth','cancel')}</div>`:''}<form novalidate id="account-form"><label for="account-email">${h(t('email'))}</label><input id="account-email" type="email" autocomplete="username" maxlength="254" required>${accountMode==='recovery'?`<p class="fine">${h(t('recoveryHelp'))}</p>`:`<label for="account-password">${h(t('password'))}</label><input id="account-password" type="password" autocomplete="${accountMode==='signup'?'new-password':'current-password'}" minlength="12" maxlength="128" required>`}<div class="actions"><button class="primary">${h(t(accountMode==='recovery'?'recover':accountMode==='signup'?'signUp':'signIn'))}</button>${button('toggle-account',accountMode==='login'?'signUp':'signIn')}</div>${accountMode==='login'?button('forgot','forgot'):''}</form>`}<div id="account-message" role="status"></div>`;
 const message=value=>{if($('#account-message'))$('#account-message').textContent=value;};
 if($('#toggle-account'))$('#toggle-account').onclick=()=>{cancelAuth();accountMode=accountMode==='login'?'signup':'login';mountAccount();};if($('#forgot'))$('#forgot').onclick=()=>{accountMode='recovery';mountAccount();};if($('#google-login')){$('#google-login').className='google-signin';$('#google-login').disabled=!native||!!pendingAuth;$('#google-login').onclick=async()=>{const button=$('#google-login');button.disabled=true;message(t('working'));try{const data=await cloudCall('google-start');if(!box.isConnected)return;pendingAuth={kind:'google',verifier:data.verifier,backend:connection.url,expires:Date.now()+600000};native.openGoogleSignIn(data.url);mountAccount();}catch(e){message(humanError(e));button.disabled=false;}};}
 if($('#cancel-auth'))$('#cancel-auth').onclick=()=>{cancelAuth();mountAccount();};
 if($('#account-form'))$('#account-form').onsubmit=async event=>{event.preventDefault();const invalid=validateForm($('#account-form'));if(invalid){message(invalid);return;}cancelAuth();const email=$('#account-email').value,password=$('#account-password')?.value,mode=accountMode;box.querySelectorAll('button').forEach(b=>b.disabled=true);message(t('working'));try{if(mode==='recovery'){if(!native?.beginAccountLink)throw Error('Recovery is unavailable');const data=await cloudCall('recovery-start',{email});pendingAuth={kind:'recovery',verifier:data.verifier,backend:connection.url,expires:Date.now()+600000};native.beginAccountLink();mountAccount();message(t('recoverySent'));return;}const data=await cloudCall(mode==='signup'?'signup':'login',{email,password});if(!box.isConnected)return;cloudSession=data.session||'';cloudEmail=data.email||'';mountAccount();message(t(data.session?'signedIn':'confirmEmail'));}catch(e){message(humanError(e));}finally{box.querySelectorAll('button').forEach(b=>b.disabled=false);if($('#account-password'))$('#account-password').value='';}};
 if($('#logout'))$('#logout').onclick=async()=>{try{await cloudCall('logout');}catch{}cloudSession='';cloudEmail='';recovering=false;cancelAuth();mountAccount();toast(t('signedOut'));};
 if($('#delete-account'))$('#delete-account').onclick=async()=>{if(!await confirmAction(t('deleteAccount'),t('accountDeleteHelp'),{typed:true}))return;const b=$('#delete-account');b.disabled=true;try{await cloudCall('delete-account',{confirm:'DELETE'});cloudSession='';cloudEmail='';recovering=false;mountAccount();toast(t('accountDeleted'));}catch(e){toast(humanError(e));b.disabled=false;}};
 if($('#password-update'))$('#password-update').onsubmit=async e=>{e.preventDefault();const invalid=validateForm($('#password-update'));if(invalid){message(invalid);return;}if($('#new-password').value!==$('#confirm-password').value){message(t('passwordMismatch'));return;}const b=$('#password-update button');b.disabled=true;try{await cloudCall('password-update',{password:$('#new-password').value});recovering=false;mountAccount();toast(t('passwordUpdated'));}catch(error){message(humanError(error));b.disabled=false;}};
}
function download(){const text=`HealthClear — ${t(current.demo?'fictional':'aiNotice')}\n${t('export')}\n${t('disclaimer')}\n\n${audioText(result)}\n\n${t('sourceText')}\n${current.text.split(/\r?\n/).map((line,i)=>`[${i+1}] ${line}`).join('\n')}\n\n${result.findings.map(f=>`${f.text} → [${f.ref+1}]`).join('\n')}\n${result.follow} → [${(result.followRefs||[result.followRef]).filter(Number.isInteger).map(i=>i+1).join(', ')}]`;if(native){native.exportSummary(text);return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='HealthClear-doctor-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'));}
window.healthclearNativeError=message=>toast(/Summary saved/.test(message)?t('exported'):/Opening your report/.test(message)?t('working'):humanError(message));
window.healthclearAudioStatus=message=>{if($('#audio-status'))$('#audio-status').textContent=t(/Finished/.test(message)?'finished':/Paused/.test(message)?'paused':/Playing/.test(message)?'playing':'audioUnavailable');};
window.healthclearReceiveFile=(base64,name,type)=>{const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));loadFile(new File([bytes],name,{type}));};
window.healthclearPdfPage=(url,index,count)=>{if(!$('#pdf-page'))return;current.pdfPage=index;$('#pdf-page').src=url;$('#pdf-number').textContent=t('page',{page:index+1,total:count});$('#pdf-prev').disabled=index===0;$('#pdf-next').disabled=index===count-1;};
window.healthclearGoogleReturn=async(code,error)=>{const pending=pendingAuth;pendingAuth=null;if(error||!pending||pending.expires<Date.now()||!connection.ready||pending.backend!==connection.url){settings();toast(t('linkExpired'));return;}settings();try{const data=await cloudCall(pending.kind==='recovery'?'recovery-exchange':'google-exchange',{code,verifier:pending.verifier});if(!connection.ready||pending.backend!==connection.url)return;cloudSession=data.session;cloudEmail=data.email;recovering=pending.kind==='recovery';mountAccount();toast(t('signedIn'));}catch(e){toast(humanError(e));mountAccount();}};
window.healthclearAndroidBack=()=>{if(document.querySelector('dialog[open]')){document.querySelector('#cancel-confirm')?.click();return;}if(page==='results')review();else if(page==='review')navigate('upload');else if(page!=='upload')navigate('upload');else native?.finishApp();};
window.addEventListener('healthclear-session-expired',()=>{cloudSession='';cloudEmail='';recovering=false;cancelAuth();if(page==='settings')mountAccount();toast(t('sessionExpired'));});
document.addEventListener('click',event=>{if(event.target.closest('#skip-link')){event.preventDefault();root.focus();root.scrollIntoView();return;}const anchor=event.target.closest('a[href]'),href=anchor?.getAttribute('href');if(href?.startsWith('#')&&['upload','history','settings'].includes(href.slice(1))){event.preventDefault();navigate(href.slice(1));}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));window.addEventListener('pagehide',()=>{clear();cancelAuth();});
render(location.hash.slice(1)||'upload');

async function refreshService(){const trigger=$('#recheck-service');if(trigger)trigger.disabled=true;document.querySelectorAll('.service-status').forEach(el=>el.textContent=t('serviceChecking'));try{if(!connection.ready)await connectLocal();if(connection.ready)service=await api('status');else service={};}catch{service={};}finally{document.querySelectorAll('.service-status').forEach(el=>el.textContent=t(service.configured?'serviceOnline':connection.ready?'servicePending':'serviceOffline'));if($('#consent+span'))$('#consent+span').textContent=t(connection.ready?'consentOnline':'consentLocal');if(trigger)trigger.disabled=false;}}
refreshService();
